@Component("dataSource-handler")
@ProcessingGroup("dataSource-processing-group")
public class DataSourceEventHandler {
	
	// core constructor
	DataSourceEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDataSourceEvent
     */
    @EventHandler
    public void handle( CreateDataSourceEvent event) {
        entityManager.persist(new DataSource(event.getDataSourceId(), event.getName(), event.getConnection(), event.getStreaming(), event.getWorkspace(), event.getProducedDatasets(), event.getPipelines(), event.getSourceType(), event.getFormat()));
    }

    /*
     * @param	event UpdateDataSourceEvent
     */
    @EventHandler
    public DataSource handle( UpdateDataSourceEvent event) {
    	entityManager.merge(new DataSource(event.getDataSourceId(), event.getName(), event.getConnection(), event.getStreaming(), event.getWorkspace(), event.getProducedDatasets(), event.getPipelines(), event.getSourceType(), event.getFormat()));
    }
    
    /*
     * @param	event DeleteDataSourceEvent
     */
    @EventHandler
    public void on( DeleteDataSourceEvent event) {
    	DataSource entity = new DataSource();
   
    	// ------------------------------------------
    	// apply the DataSourceId
    	// ------------------------------------------
    	entity.setDataSourceId( event.getDataSourceId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DataSourceRepository dataSourceEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DataSourceEventHandler.class.getName());

}
